		switch table {
		case "ID":
			n := judgmentFlowNode{Line: i + 1}
			if len(cells) > 0 {
				n.ID = cells[0]
			}
			if len(cells) > 1 {
				n.Kind = cells[1]
			}
			if len(cells) > 2 {
				n.Label = cells[2]
			}
			if !judgmentFlowIDRe.MatchString(n.ID) {
				add("決定表 %d 行目: ID %q はノード ID の形 (D・E・A・H・R と番号) ではありません", n.Line, n.ID)
				continue
			}
			if prev, dup := idAt[n.ID]; dup {
				add("%s の行が決定表で重複しています (%d 行目と %d 行目)", n.ID, prev, n.Line)
				continue
			}
			idAt[n.ID] = n.Line
			if strings.ContainsAny(n.Label, "\"\\") {
				// 図のラベルは %q で書き出すが、mermaid は \" や \\ を解さない。
				add("%s の表示名に \" か \\ があります (図のラベルに出せない)", n.ID)
			}
			doc.Nodes = append(doc.Nodes, n)
		case "始点":
			tr := judgmentFlowTransition{Line: i + 1}
			if len(cells) > 0 {
				tr.From = cells[0]
			}
			if len(cells) > 1 {
				tr.Cond = cells[1]
			}
			if len(cells) > 2 {
				tr.To = cells[2]
			}
			doc.Transitions = append(doc.Transitions, tr)
		}
	}
	if fenceLine >= 0 {
		add("%d 行目で開いた ``` のフェンスが閉じていません", fenceLine+1)
	}
	return doc, problems
}

// judgmentFlowCells は表の行をセルに分ける。前後のパイプを落とし、各セルの
// 空白を詰める。
func judgmentFlowCells(line string) []string {
	s := strings.TrimSpace(line)
	s = strings.TrimPrefix(s, "|")
	s = strings.TrimSuffix(s, "|")
	parts := strings.Split(s, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

// renderJudgmentFlowDiagram は決定表と遷移表から mermaid の図を組み立てる。
// ノードは決定表の順、遷移は遷移表の順、色は種類ごと (採択・保留・却下・評価の順) に
// 出す。判定は菱形、それ以外は角丸でない箱。
