// 出す。判定は菱形、それ以外は角丸でない箱。
func renderJudgmentFlowDiagram(doc *judgmentFlowDoc) string {
	var b strings.Builder
	b.WriteString("flowchart TD\n")
	for _, n := range doc.Nodes {
		label := fmt.Sprintf("%s: %s", n.ID, n.Label)
		if strings.HasPrefix(n.ID, "D") {
			fmt.Fprintf(&b, "  %s{%q}\n", n.ID, label)
		} else {
			fmt.Fprintf(&b, "  %s[%q]\n", n.ID, label)
		}
	}
	b.WriteString("\n")
	for _, tr := range doc.Transitions {
		if tr.Cond == "" {
			fmt.Fprintf(&b, "  %s --> %s\n", tr.From, tr.To)
		} else {
			fmt.Fprintf(&b, "  %s -- %s --> %s\n", tr.From, tr.Cond, tr.To)
		}
	}
	b.WriteString("\n")
	for _, kind := range []string{"A", "H", "R", "E"} {
		for _, n := range doc.Nodes {
			if strings.HasPrefix(n.ID, kind) {
				fmt.Fprintf(&b, "  style %s %s\n", n.ID, judgmentFlowStyle[kind])
			}
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// judgmentFlowProblems は判定フローの正本を検査する。検査は (0) 文書の構造
// (parseJudgmentFlow が確かめる — フェンスの閉じ・表の重複・ID の形と重複・表示名の
// 文字)、(1) 図と 2 つの表があるか、(2) 決定表 (種類と ID の整合・表示名の有無)、
// (3) 遷移表 (始点と遷移先の実在・重複)、(4) ノードの種類ごとの遷移の規則と
// 到達可能性、(5) 図の鮮度 (表から生成し直した結果と一致するか)。構造に問題が
// ある間は表の意味を見ず、表に問題がある間は鮮度を比べない (直せば次が出る —
// 記録のサマリと同じ扱い)。
//
// ファイルが無いとき、在り処の指定 (origin) が無ければ未導入として通し、
// 指定があれば報告する (検査が行われないまま緑になるのを避ける)。
// files は他の検査とシグネチャを揃えるための引数で、使わない。
func judgmentFlowProblems(_ []string, readFile func(string) ([]byte, error), origin string) []string {
	data, err := readFile(judgmentFlowPath)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			if origin != "" {
				return []string{fmt.Sprintf(
					"%s: %s が指す判定フローの正本が存在しません (検査が行われないまま緑になるため報告する)",
					judgmentFlowPath, origin)}
			}
			return nil
		}
		return []string{fmt.Sprintf("%s: 読み込みに失敗しました: %v", judgmentFlowPath, err)}
	}
	doc, problems := parseJudgmentFlow(data)
	if len(problems) > 0 {
		sort.Strings(problems)
		return problems
	}
	problems = judgmentFlowTableProblems(&doc)
	if !doc.HasDiagram {
		problems = append(problems, fmt.Sprintf("%s: mermaid の図が見つかりません (表から `%s` で生成する)", judgmentFlowPath, judgmentFlowRegenerateHint))
	}
	if len(problems) > 0 {
		sort.Strings(problems)
		return problems
	}
	if want := renderJudgmentFlowDiagram(&doc); doc.Diagram != want {
		problems = append(problems, fmt.Sprintf(
			"%s: 図が正本 (決定表・遷移表) と食い違っています (`%s` で再生成する。図は手で編集しない)",

			"%s: 図が正本 (決定表・遷移表) と食い違っています (`%s` で再生成する。図は手で編集しない)",
			judgmentFlowPath, judgmentFlowRegenerateHint))
	}
	return problems
}

