func judgmentFlowRead(content string) func(string) ([]byte, error) {
	return func(_ string) ([]byte, error) { return []byte(content), nil }
}

func judgmentFlowCheck(content string) []string {
	return judgmentFlowProblems([]string{judgmentFlowPath}, judgmentFlowRead(content), "")
}

func judgmentFlowExpectOne(t *testing.T, content, want string) {
	t.Helper()
	problems := judgmentFlowCheck(content)
	if len(problems) != 1 || !strings.Contains(problems[0], want) {
		t.Fatalf("期待した報告 (%s) と違う: %v", want, problems)
	}
